ALTER TABLE projects_receipts ADD COLUMN project_id TEXT;
UPDATE projects_receipts SET project_id=result_id;
ALTER TABLE projects_events ADD COLUMN project_id TEXT;
UPDATE projects_events SET project_id=aggregate_id;
CREATE TABLE projects_frozen_scopes (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('frozen','purging','purged')), PRIMARY KEY(workspace_id,project_id));
CREATE TABLE projects_purge_bypass (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, PRIMARY KEY(workspace_id,project_id));
CREATE TRIGGER projects_freeze_grants_insert BEFORE INSERT ON projects_grants WHEN EXISTS(SELECT 1 FROM projects_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id=NEW.project_id)) AND NOT EXISTS(SELECT 1 FROM projects_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=NEW.project_id)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER projects_freeze_grants_update BEFORE UPDATE ON projects_grants WHEN (EXISTS(SELECT 1 FROM projects_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id=NEW.project_id)) AND NOT EXISTS(SELECT 1 FROM projects_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=NEW.project_id))) OR (EXISTS(SELECT 1 FROM projects_frozen_scopes f WHERE f.workspace_id=OLD.workspace_id AND (f.project_id='' OR f.project_id=OLD.project_id)) AND NOT EXISTS(SELECT 1 FROM projects_purge_bypass b WHERE b.workspace_id=OLD.workspace_id AND (b.project_id='' OR b.project_id=OLD.project_id))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER projects_freeze_grants_delete BEFORE DELETE ON projects_grants WHEN EXISTS(SELECT 1 FROM projects_frozen_scopes f WHERE f.workspace_id=OLD.workspace_id AND (f.project_id='' OR f.project_id=OLD.project_id)) AND NOT EXISTS(SELECT 1 FROM projects_purge_bypass b WHERE b.workspace_id=OLD.workspace_id AND (b.project_id='' OR b.project_id=OLD.project_id)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
